                        <button type="button" className="btn-cancel" onClick={handleCancel} autoFocus>
                            Cancel
                        </button>
                        <button type="button" className="btn-delete" onClick={handleDelete}>
                            Delete
                        </button>
                    </div>
                </dialog>
            );
        }

        // Main Image Preview Component
        function ImagePreview() {
            const [isDialogOpen, setIsDialogOpen] = useState(false);
            const [isDeleted, setIsDeleted] = useState(false);
            const triggerRef = useRef(null);

            const handleDelete = () => {
                setIsDeleted(true);
            };

            // Handle focus restoration safely if the item gets deleted and the trigger is removed
            useEffect(() => {
                if (isDeleted) {
                    // In a real application, you might move focus to a status message or back to a gallery.
                    // Here we move it to the status message container for screen reader awareness.
                    document.getElementById('status-message')?.focus();
                }
            }, [isDeleted]);

            if (isDeleted) {
                return (
                    <div id="status-message" tabIndex="-1" aria-live="polite" style={{ outline: 'none' }}>
                        <p>Image has been successfully deleted.</p>
                    </div>
                );
            }

            return (
                <section className="image-preview" aria-label="Image preview">
                    <img src="https://picsum.photos/seed/a11y/600/400" alt="A scenic mountain landscape" />
                    <button 
                        ref={triggerRef}
                        type="button" 
                        className="trigger" 
                        onClick={() => setIsDialogOpen(true)}
                    >
                        Delete Image
                    </button>

                    <ConfirmDeleteDialog 
                        isOpen={isDialogOpen} 
                        onClose={() => setIsDialogOpen(false)} 
                        onDelete={handleDelete}
                    />
                </section>
            );
        }

        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(<ImagePreview />);
